<!-- 模块职责：负责人审核收件箱；批准与正式执行是两个独立操作。 -->
<script setup>
import Icon from '../components/Icon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { dateTime } from '../format'
import { watch } from 'vue'
const props = defineProps({ store: Object })
const store = props.store, s = store.state, isManager = store.manager
// Entering the inbox triggers one load. Busy handoffs wait until their read completes.
s.reviewsAttempted = false
watch([() => s.user, () => s.busy], () => {
  if (isManager.value && !s.busy && !s.reviewsAttempted) store.loadReviews()
}, { immediate: true })
</script>
<template>
  <div v-if="!isManager" class="card permission-card"><span class="empty-icon"><Icon name="shield" :size="30" /></span><h2>审核需要负责人身份</h2><p>员工可以提交任务和查看自己的处理进度。<br />请退出登录后使用业务负责人演示账户进入审核待办。</p></div>
  <template v-else>
    <section class="card inbox-card">
      <div class="card-header"><div><h2>审核收件箱 <span class="inbox-count">{{ s.reviewTotal }}</span></h2><p>所有员工提交的审核建议，按提交时间从早到晚排列。</p></div><button class="button secondary small" :disabled="s.busy" @click="store.loadReviews()"><Icon name="refresh" :size="15" />刷新列表</button></div>
      <form class="inbox-toolbar" @submit.prevent="store.loadReviews(true)"><label><span class="sr-only">审核状态</span><select v-model="s.reviewFilter" aria-label="审核状态" :disabled="s.busy" @change="store.loadReviews(true)"><option value="pending">待审核</option><option value="approved">已批准</option><option value="rejected">已拒绝</option><option value="all">全部状态</option></select></label><div class="inline-form"><Icon name="search" :size="16" /><input v-model="s.reviewQuery" aria-label="搜索审核建议" :disabled="s.busy" maxlength="128" placeholder="搜索订单号或审核编号" /><button class="button secondary small" :disabled="s.busy">筛选</button></div></form>
      <div v-if="s.reviewsError" class="inbox-error" role="status"><Icon name="shield" :size="20" /><div><strong>暂时无法读取审核列表</strong><p>{{ s.reviewsError }}</p><button class="text-button" :disabled="s.busy" @click="store.loadReviews()">重新加载列表</button></div></div>
      <div v-else-if="!s.reviewInbox.length" class="empty-state inbox-empty"><span class="empty-icon"><Icon :name="s.busy ? 'clock' : 'check'" :size="25" /></span><h3>{{ s.busy ? '正在读取审核建议' : s.reviewFilter === 'pending' && !s.reviewQuery ? '当前没有待审核建议' : '没有符合筛选条件的建议' }}</h3><p>{{ s.busy ? '请稍候，列表会在读取完成后更新。' : '员工生成待审核建议后，会在这里显示。可以刷新列表查看最新提交。' }}</p></div>
      <div v-else class="inbox-table-wrap"><table class="inbox-table"><thead><tr><th>订单与建议</th><th>提交时间</th><th>状态</th><th><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="item in s.reviewInbox" :key="item.approval_id" :class="{ 'inbox-selected': s.review?.approval_id === item.approval_id }"><td><strong class="mono">{{ item.order_id }}</strong><p class="inbox-summary">{{ item.description }}</p><small class="mono selectable">{{ item.approval_id }}</small></td><td class="inbox-time">{{ dateTime(item.submitted_at) }}</td><td><StatusBadge :status="item.approval_status" /></td><td><button class="text-button inbox-open" :disabled="s.busy" :aria-label="`查看建议 ${item.approval_id}`" @click="store.selectReview(item.approval_id)">查看建议 <Icon name="arrow" :size="14" /></button></td></tr></tbody></table></div>
      <div v-if="s.reviewTotal && !s.reviewsError" class="inbox-pagination"><span>共 {{ s.reviewTotal }} 条 · 第 {{ Math.floor(s.reviewOffset / s.reviewLimit) + 1 }} 页</span><div><button class="button secondary small" :disabled="s.busy || s.reviewOffset === 0" @click="store.reviewPage(-1)">上一页</button><button class="button secondary small" :disabled="s.busy || s.reviewOffset + s.reviewLimit >= s.reviewTotal" @click="store.reviewPage(1)">下一页</button></div></div>
      <p v-if="s.reviewUnavailable" class="inbox-warning">有 {{ s.reviewUnavailable }} 条历史记录暂不可用，未混入可审核列表，请核对后端检查点。</p>
    </section>
    <details class="card direct-review" :open="Boolean(s.approvalInput)"><summary>按审核编号直接打开 <small>辅助查找</small></summary><form class="inline-form" @submit.prevent="store.loadReview"><Icon name="search" :size="18" /><input v-model="s.approvalInput" aria-label="审核编号" :disabled="s.busy" placeholder="输入已有 approval_id" /><button class="button secondary" :disabled="s.busy || !s.approvalInput.trim()">读取审核</button></form></details>
  <section v-if="!s.review" class="card empty-state tall-empty"><span class="empty-icon"><Icon name="shield" :size="30" /></span><h3>选择一份建议，开始审核</h3><p>点击上方列表的“查看建议”，阅读订单事实与政策依据。<br />批准与正式执行是两个独立操作。</p></section>
  <div v-else class="two-column"><section class="card"><div class="card-header"><div><h2>发货延迟核查建议</h2><p class="mono selectable">{{ s.review.approval_id }}</p></div><StatusBadge :status="s.review.proposal.approval_status" /></div><div class="card-body"><dl class="detail-list"><dt>订单编号</dt><dd class="mono">{{ s.review.proposal.order_id }}</dd><dt>问题类型</dt><dd>发货延迟核查 <span class="subtle">shipping_delay</span></dd><dt>评估时刻</dt><dd>{{ dateTime(s.review.proposal.checked_at) }}</dd></dl><h3 class="subheading">业务事实与处理建议</h3><div class="prose-box">{{ s.review.proposal.description }}</div><h3 class="subheading">政策依据</h3><div v-for="(source, i) in s.review.proposal.policy_sources" :key="source.chunk_id" class="source-item"><span class="source-index">{{ i + 1 }}</span><div><strong>{{ source.document_title }}</strong><p>{{ source.section }}</p><small class="selectable">{{ source.source }}</small></div></div><div v-if="!s.review.proposal.policy_sources.length" class="inline-error">没有政策来源，请核对建议完整性。</div><div class="button-row section-divider"><button class="button primary" :disabled="s.busy || s.review.proposal.approval_status !== 'pending'" @click="store.decide('approved')"><Icon name="check" :size="17" />批准建议</button><button class="button secondary" :disabled="s.busy || s.review.proposal.approval_status !== 'pending'" @click="store.decide('rejected')">拒绝建议</button><button class="text-button" :disabled="s.busy" @click="store.loadReview">重新查询</button></div><p class="footnote">只有负责人可以提交决定；已完成的审核不能重复批准或拒绝。</p><dl v-if="s.review.reviewer_id" class="detail-list compact"><dt>审核人</dt><dd>{{ s.review.reviewer_id }}</dd><dt>审核时间</dt><dd>{{ dateTime(s.review.reviewed_at) }}</dd></dl></div></section>
  <aside><section class="card"><div class="card-header"><h2>正式工单执行</h2><Icon name="ticket" :size="19" /></div><div class="card-body"><template v-if="s.execution?.status === 'success'"><StatusBadge status="success" /><h3 class="subheading">工单编号</h3><p class="mono selectable">{{ s.execution.ticket_id }}</p><button class="button primary full-width" :disabled="s.busy" @click="s.ticketInput = s.execution.ticket_id; store.navigate('tickets'); store.loadTicket()">查看正式工单 <Icon name="arrow" :size="16" /></button></template><template v-else><p class="muted">{{ s.review.proposal.approval_status === 'approved' ? '建议已批准。执行前，后端会再次核对当前订单和审核记录。' : s.review.proposal.approval_status === 'rejected' ? '建议已拒绝，禁止创建正式工单。' : '先完成负责人审核，再单独执行正式工单创建。' }}</p><div v-if="s.execution?.error" class="inline-error">{{ s.execution.error }}</div><button class="button primary full-width" :disabled="s.busy || !s.reviewReady || s.review.proposal.approval_status !== 'approved'" @click="store.execute">执行已批准建议 <Icon name="arrow" :size="16" /></button></template><p class="footnote">执行成功后，原任务创建者需刷新任务状态。负责人不能越权读取员工任务。</p></div></section><section class="aside-note"><Icon name="shield" :size="22" /><h3>写入边界始终明确</h3><p>审核通过不代表工单已创建。以执行接口返回的正式工单编号为准。</p></section></aside></div></template>
</template>
